create table if not exists public.mncc_services (id bigint generated by default as identity primary key,title text not null,description text not null default '',bullets jsonb not null default '[]'::jsonb,published boolean not null default true,display_order integer not null default 100,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mncc_cases (id bigint generated by default as identity primary key,title text not null,description text not null default '',outcome text not null default '',tags jsonb not null default '[]'::jsonb,published boolean not null default true,display_order integer not null default 100,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mncc_settings (id bigint generated by default as identity primary key,setting_key text not null unique,setting_value text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mncc_leads (id bigint generated by default as identity primary key,name text not null,email text not null,company text,service text,message text not null,country text,created_at timestamptz not null default now());
alter table public.mncc_services enable row level security; alter table public.mncc_cases enable row level security; alter table public.mncc_settings enable row level security; alter table public.mncc_leads enable row level security;
revoke all on table public.mncc_services,public.mncc_cases,public.mncc_settings,public.mncc_leads from anon,authenticated;
grant select,insert,update,delete on table public.mncc_services,public.mncc_cases,public.mncc_settings,public.mncc_leads to service_role;
grant usage,select on sequence public.mncc_services_id_seq,public.mncc_cases_id_seq,public.mncc_settings_id_seq,public.mncc_leads_id_seq to service_role;
create index if not exists mncc_services_public_idx on public.mncc_services(published,display_order);
create index if not exists mncc_cases_public_idx on public.mncc_cases(published,display_order);
create index if not exists mncc_leads_created_idx on public.mncc_leads(created_at desc);